 if(argc!=3)return 2;const auto dir=std::filesystem::path(argv[2]);std::filesystem::create_directories(dir);const auto placed=dir/"placed.vrm",badges=dir/"accessories.vrm",input=dir/"joint-mesh.vrm";vrm_source_fixture::source_variant(argv[1],placed,2);const auto source_nodes=vrm_source_fixture::with_rigid_accessories(placed,badges);const auto spacer=vrm_rest_fixture::with_joint_mesh(badges,input);ImportAuthoringOptions options;options.paint_resolution=64;auto prepared=prepare_authoring_import(Scene{},input,options);check(prepared.objects.size()==23,"Actual original source instance includes19skins,3accessories and a true rigid mesh on the weighted head joint");
